<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt #{{ $booking->id }}</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fb;color:#172033;font-family:Arial,sans-serif}.card{max-width:640px;margin:28px auto;background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:26px}.brand{display:flex;align-items:center;gap:12px;padding-bottom:20px;border-bottom:1px solid #e2e8f0}.brand img{max-width:55px;max-height:55px}.brand strong{font-size:22px}.amount{font-size:36px;font-weight:700;margin:22px 0}.row{padding:10px 0;border-bottom:1px solid #eef2f7}.row span{float:right}.muted{color:#64748b}@media(max-width:680px){.card{margin:0;border-radius:0;min-height:100vh}}</style></head><body><main class="card"><div class="brand">@if($booking->company?->logo)<img src="{{ $booking->company->logo }}" alt="Logo">@endif <strong>{{ $booking->company?->name ?? config('app.name') }}</strong></div><p class="muted">Payment receipt · Booking #{{ $booking->id }}</p><div class="amount">{{ strtoupper($booking->latestPayment?->currency ?? 'USD') }} {{ number_format((float)($booking->latestPayment?->captured_amount ?? $booking->final_price),2) }}</div><div class="row">Payment status <span>{{ ucwords(str_replace('_',' ',$booking->latestPayment?->status ?? $booking->payment_status)) }}</span><div style="clear:both"></div></div><div class="row">Trip status <span>{{ ucwords(str_replace('_',' ',$booking->status)) }}</span><div style="clear:both"></div></div><div class="row">Pickup <span>{{ $booking->pickup_address }}</span><div style="clear:both"></div></div>@if($booking->dropoff_address)<div class="row">Drop-off <span>{{ $booking->dropoff_address }}</span><div style="clear:both"></div></div>@endif <div class="row">Vehicle class <span>{{ $booking->vehicleClass?->name ?? '—' }}</span><div style="clear:both"></div></div><p class="muted" style="margin-top:22px;">This read-only receipt link does not require a login.</p></main></body></html>
